public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Changes the list of pinned gifts on the current user's or the channel's profile page; requires can_post_messages administrator right in the channel chat
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SetPinnedGiftsAsync(MessageSender ownerId = default, string[] receivedGiftIds = default)
    {

           using var activity =  StartCallActivity("SetPinnedGiftsAsync", typeof(SetPinnedGifts).FullName ?? "SetPinnedGiftsAsync");

           try
           {
             return client.SetPinnedGiftsAsync(ownerId, receivedGiftIds);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
